function build(api) {
  api.name('Pikachu');
  const C_Y = 0xFFCC00, C_YD = 0xE6B800, C_BK = 0x111111, C_RD = 0xCC3333, C_BR = 0x8B4513;

  api.group('body', '躯干');
    api.box({w:2.8, h:2.2, d:3.5, pos:[0, 1.6, 0], color:C_Y});
    api.box({w:2.5, h:1.8, d:2.0, pos:[0, 1.4, -1.5], color:C_Y});
    api.box({w:0.5, h:0.08, d:2.2, pos:[-0.6, 2.72, -0.2], color:C_BR});
    api.box({w:0.5, h:0.08, d:2.2, pos:[0.6, 2.72, -0.2], color:C_BR});
  api.endGroup();

  api.group('head', '头部');
    api.sphere({r:1.3, pos:[0, 2.8, 2.2], color:C_Y});
    api.box({w:1.0, h:0.5, d:0.6, pos:[0, 2.2, 3.3], color:C_Y});
    api.box({w:0.8, h:0.15, d:0.65, pos:[0, 2.15, 3.35], color:C_BK});
    api.sphere({r:0.35, pos:[0.7, 3.0, 3.1], color:C_RD});
    api.sphere({r:0.35, pos:[-0.7, 3.0, 3.1], color:C_RD});
    api.poly({r:0.2, pos:[0.4, 3.15, 3.35], color:C_BK});
    api.poly({r:0.2, pos:[-0.4, 3.15, 3.35], color:C_BK});
    api.cone({r:0.35, h:1.2, along:'+Y', pos:[0.6, 4.3, 2.0], color:C_Y});
    api.cone({r:0.2, h:0.4, along:'+Y', pos:[0.6, 4.85, 1.85], color:C_BK});
    api.cone({r:0.35, h:1.2, along:'+Y', pos:[-0.6, 4.3, 2.0], color:C_Y});
    api.cone({r:0.2, h:0.4, along:'+Y', pos:[-0.6, 4.85, 1.85], color:C_BK});
  api.endGroup();

  api.group('tail', '尾巴');
    api.chain({waypoints:[[0, 2.0, -2.5], [0, 2.8, -3.2], [0, 3.8, -2.8], [0, 4.5, -3.5]], r:0.35, rEnd:0.25, color:C_Y});
    api.chain({waypoints:[[0, 2.0, -2.5], [0, 2.6, -2.9]], r:0.3, rEnd:0.2, color:C_BR});
  api.endGroup();

  api.mirror('x');
  api.group('leftArm', '左前腿');
    api.chain({waypoints:[[-1.4, 1.6, 1.2], [-1.6, 0.6, 1.0], [-1.5, 0.15, 1.2]], r:0.3, rEnd:0.25, jointIds:['shoulder','elbow','paw'], color:C_Y});
  api.endGroup();
  api.group('leftLeg', '左后腿');
    api.chain({waypoints:[[-1.2, 1.4, -1.5], [-1.4, 0.5, -1.2], [-1.3, 0.15, -1.4]], r:0.35, rEnd:0.28, jointIds:['hip','knee','paw'], color:C_Y});
  api.endGroup();
  api.endMirror();
}
